parameters.jsonBody:
={
  "q": "site:linkedin.com/in (\"BITS Pilani\" OR \"Birla Institute of Technology and Science\") \"{{$json.company}}\" Singapore"
}

parameters.jsCode:
const allItems = $input.all();

let output = [];

for (const inputItem of allItems) {

  const company =
    inputItem.json.searchParameters?.q?.match(/"([^"]+)" Singapore$/)?.[1] || "";

  const results = inputItem.json.organic || [];

  const filtered = results
    .filter(item => {
      const text = (
        (item.title || "") +
        " " +
        (item.snippet || "")
      ).toLowerCase();

      return (
        text.includes("bits pilani") ||
        text.includes("birla institute of technology and science")
      );
    })
    .map(item => {

      const title = item.title || "";

      let name = title.split("-")[0].trim();

      let position = "";
      if (title.includes("-")) {
        position = title.split("-").slice(1).join("-").trim();
      }

      return {
        json: {
          Company: company,
          AlumName: name,
          LinkedInProfile: item.link || "",
          Post: position,
          Snippet: item.snippet || ""
        }
      };
    });

  output.push(...filtered);
}

return output;

