  const profile = item.json.LinkedInProfile;

  if (!profile || seen.has(profile)) {
    return false;
  }

  seen.add(profile);
  return true;
});

return items.map(item => {

  const post = (item.json.Post || "").toLowerCase();

  let score = 1;
  let level = "Entry";

  if (
    post.includes("founder") ||
    post.includes("co-founder") ||
    post.includes("ceo") ||
    post.includes("cto") ||
    post.includes("cfo")
  ) {
    score = 20;
    level = "Executive";
  }

  else if (
    post.includes("partner") ||
    post.includes("managing director")
  ) {
    score = 15;
    level = "Executive";
  }

  else if (
    post.includes("executive director") ||
    post.includes("director")
  ) {
    score = 12;
    level = "Director";
  }

  else if (
    post.includes("vice president") ||
    post.includes("vp")
  ) {
    score = 10;
    level = "VP";
  }

  else if (
    post.includes("head of") ||
    post.includes("principal")
  ) {
    score = 8;
    level = "Leadership";
  }

  else if (
    post.includes("manager") ||
    post.includes("lead")
  ) {
    score = 6;
    level = "Manager";
  }

  else if (
    post.includes("senior")
  ) {
    score = 4;
    level = "Senior";
  }

  else if (
    post.includes("engineer") ||
    post.includes("developer") ||
    post.includes("analyst") ||
    post.includes("associate")
  ) {
    score = 3;
    level = "Individual Contributor";
  }

  item.json.SeniorityScore = score;
  item.json.SeniorityLevel = level;

  return item;

});
